{"implementation": "def solve(case):
    nodes = case['nodes']
    core = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    idx = {node: i for i, node in enumerate(nodes)}
    parent = list(range(n))
    rank = [0] * n
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    edges = []
    for d in distances:
        u, v, w = d[0], d[1], d[2]
        if u == v:
            continue
        if u > v:
            u, v = v, u
        mw = max(core[u], core[v], w)
        edges.append((mw, u, v))
    edges.sort(key=lambda x: (x[0], x[1], x[2]))
    mst_edges = []
    total_weight = 0.0
    for weight, u, v in edges:
        if union(idx[u], idx[v]):
            mst_edges.append([u, v, weight])
            total_weight += weight
            if len(mst_edges) == n - 1:
                break
    if len(mst_edges) != n - 1:
        raise ValueError("Graph is disconnected")
    return {"mst_edges": mst_edges, "total_weight": total_weight}
"}
